    v_high_seen boolean := false;

    r_rest RECORD;
    r_stu  RECORD;
    r_kind RECORD;

    v_old_kind_id integer;
BEGIN
    /* Pick the mode from the initial threshold. */
    IF v_initial_threshold < 3 THEN
        v_state := 'MINIMAL_PROCESS';

        FOR r_rest IN
            SELECT "ResID", "ResName", "Address"
            FROM "Restaurant"
            WHERE "ResID" < arg1
              AND "ResName" LIKE arg2
            ORDER BY "ResID"
        LOOP
            v_handled_count := v_handled_count + 1;

            IF r_rest."ResID" > 25 THEN
                UPDATE "Restaurant"
                SET "ResName" = 'PROMOTED'
                WHERE "ResID" = r_rest."ResID";
            ELSIF r_rest."Address" = v_operation THEN
                DELETE FROM "Visits_Restaurant"
                WHERE "ResID" = r_rest."ResID";

                DELETE FROM "Type_Of_Restaurant"
                WHERE "ResID" = r_rest."ResID";

                DELETE FROM "Restaurant"
                WHERE "ResID" = r_rest."ResID"
                  AND "ResName" = r_rest."ResName";
            ELSE
                UPDATE "Restaurant"
                SET "Address" = 'PENDING'
                WHERE "ResID" = r_rest."ResID";
            END IF;

            IF v_handled_count = v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_initial_threshold < 8 THEN
        v_state := 'STANDARD_PROCESS';

        FOR r_stu IN
            SELECT "StuID", "LName", "city_code"
            FROM "Student"
            WHERE "StuID" BETWEEN (arg4 - 5) AND (arg4 + 15)
            ORDER BY "StuID"
        LOOP
            v_handled_count := v_handled_count + 1;

            IF r_stu."city_code" = v_operation THEN
                UPDATE "Student"
                SET "Sex" = 'U'
                WHERE "StuID" = r_stu."StuID";
            END IF;

            IF r_stu."LName" = arg5 THEN
                UPDATE "Student"
                SET "city_code" = 'MATCHED'
                WHERE "StuID" = r_stu."StuID";
            END IF;

            IF r_stu."LName" LIKE 'ACTIVE%' THEN
                UPDATE "Student"
                SET "LName" = 'PROCESSED'
                WHERE "StuID" = r_stu."StuID";
            ELSIF r_stu."StuID" > (arg4 + 5) THEN
                v_threshold := v_threshold + r_stu."StuID";
            ELSE
                DELETE FROM "Student"
                WHERE "StuID" = r_stu."StuID"
                  AND "LName" = 'EXPIRED';
            END IF;

            IF v_handled_count = v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

