        v_state := 'ENHANCED_PROCESS';

        FOR r_kind IN
            SELECT "ResTypeID"
            FROM "Restaurant_Type"
            WHERE "ResTypeID" > (arg6 - 20)
            ORDER BY "ResTypeID"
        LOOP
            v_handled_count := v_handled_count + 1;

            v_old_kind_id := r_kind."ResTypeID";

            IF v_old_kind_id < 50 THEN
                v_status := 'LOW_PRIORITY';
            ELSIF v_old_kind_id < 150 THEN
                v_status := 'MEDIUM_PRIORITY';
            ELSE
                v_status := 'HIGH_PRIORITY';
                v_high_seen := true;
            END IF;

            /* Add 10 to restaurant-kind numbers currently equal to the fetched original number. */
            UPDATE "Type_Of_Restaurant"
            SET "ResTypeID" = "ResTypeID" + 10
            WHERE "ResTypeID" = v_old_kind_id;

            UPDATE "Restaurant_Type"
