            FROM "Restaurant_Type"
            WHERE "ResTypeID" > 200
        )
        UPDATE "Restaurant_Type" rt
        SET "ResTypeID" = tr.new_id
        FROM to_renumber tr
        WHERE rt."ResTypeID" = tr.old_id;
