            SELECT "ResTypeID" AS old_id, "ResTypeID" * 2 AS new_id
            FROM "Restaurant_Type"
            WHERE "ResTypeID" > 100
        )
        UPDATE "Type_Of_Restaurant" tor
        SET "ResTypeID" = m.new_id
        FROM m
        WHERE tor."ResTypeID" = m.old_id;

        WITH m AS (
            SELECT "ResTypeID" AS old_id, "ResTypeID" * 2 AS new_id
            FROM "Restaurant_Type"
            WHERE "ResTypeID" > 100
        )
        UPDATE "Restaurant_Type" rt
        SET "ResTypeID" = m.new_id
        FROM m
        WHERE rt."ResTypeID" = m.old_id;

    ELSIF v_state = 'ARCHIVE_MODE' THEN
        DELETE FROM "Visits_Restaurant" vr
        WHERE vr."ResID" IN (
            SELECT "ResID"
            FROM "Restaurant"
            WHERE "Address" = 'ARCHIVED'
              AND "ResID" < (v_threshold - 10)
        );

        DELETE FROM "Type_Of_Restaurant" tor
        WHERE tor."ResID" IN (
            SELECT "ResID"
            FROM "Restaurant"
            WHERE "Address" = 'ARCHIVED'
              AND "ResID" < (v_threshold - 10)
        );

        DELETE FROM "Restaurant"
        WHERE "Address" = 'ARCHIVED'
          AND "ResID" < (v_threshold - 10);

    ELSIF v_handled_count > 15 THEN
        UPDATE "Student"
        SET "LName" = 'BULK_PROCESSED'
        WHERE "StuID" BETWEEN arg4 AND (arg4 + 50);

    ELSE
        UPDATE "Restaurant"
        SET "ResName" = v_operation
        WHERE "ResID" > v_threshold;
    END IF;
